    co_nguy_co_phan_ve BOOLEAN GENERATED ALWAYS AS (
        co_kho_tho_kho_khe_nghen_hong
        OR co_chong_mat_tuc_nguc_sap_ngat
        OR co_sung_moi_luoi_co_hong
        OR co_dau_bung_non_lien_tuc
    ) STORED,
    ket_qua_dieu_huong VARCHAR(30) GENERATED ALWAYS AS (
        CASE
            WHEN co_kho_tho_kho_khe_nghen_hong
              OR co_chong_mat_tuc_nguc_sap_ngat
              OR co_sung_moi_luoi_co_hong
              OR co_dau_bung_non_lien_tuc
            THEN 'NGUY_CO_PHAN_VE'
            ELSE 'CHUYEN_BUOC_1'
        END
    ) STORED,

    xac_nhan_muon_goi_cap_cuu       BOOLEAN,
    da_nhan_nut_goi_cap_cuu         BOOLEAN NOT NULL DEFAULT FALSE,
    so_dien_thoai_cap_cuu           VARCHAR(20),
    thoi_diem_nhan_nut_goi          TIMESTAMPTZ,
    thoi_diem_bat_dau               TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
