    thoi_diem_cap_nhat              TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_sanglocbaodongdo PRIMARY KEY (ma_luot_sang_loc),
    CONSTRAINT uq_sanglocbaodongdo_phien UNIQUE (ma_phien_ung_dung),
    CONSTRAINT fk_sanglocbaodongdo_benhnhan FOREIGN KEY (ma_benh_nhan)
        REFERENCES public.benhnhan (ma_benh_nhan) ON DELETE RESTRICT,
    CONSTRAINT ck_sanglocbaodongdo_phien_ban CHECK (
        btrim(phien_ban_bo_cau_hoi) <> ''
    ),
    CONSTRAINT ck_sanglocbaodongdo_thoi_gian CHECK (
        thoi_diem_hoan_tat >= thoi_diem_bat_dau
    ),
    CONSTRAINT ck_sanglocbaodongdo_xac_nhan CHECK (
        (co_nguy_co_phan_ve AND xac_nhan_muon_goi_cap_cuu IS NOT NULL)
        OR (NOT co_nguy_co_phan_ve AND xac_nhan_muon_goi_cap_cuu IS NULL)
    ),
    CONSTRAINT ck_sanglocbaodongdo_goi_cap_cuu CHECK (
        (
            da_nhan_nut_goi_cap_cuu
            AND co_nguy_co_phan_ve
            AND xac_nhan_muon_goi_cap_cuu IS TRUE
            AND thoi_diem_nhan_nut_goi IS NOT NULL
            AND so_dien_thoai_cap_cuu IS NOT NULL
            AND btrim(so_dien_thoai_cap_cuu) <> ''
        )
        OR (
            NOT da_nhan_nut_goi_cap_cuu
            AND thoi_diem_nhan_nut_goi IS NULL
            AND so_dien_thoai_cap_cuu IS NULL
        )
    )
);

