        tien_su_di_ung IS NULL OR tien_su_di_ung IN ('CO', 'KHONG', 'KHONG_RO')
    ),
    CONSTRAINT ck_tsbt_phan_ve_ghi_ro CHECK (btrim(tien_su_phan_ve_ghi_ro) <> ''),
    CONSTRAINT ck_tsbt_viem_nhiem_man_ghi_ro CHECK (btrim(tien_su_viem_nhiem_man_ghi_ro) <> ''),
    CONSTRAINT ck_tsbt_benh_khac_ghi_ro CHECK (btrim(tien_su_benh_khac_ghi_ro) <> '')
);

