    )
);

CREATE TABLE public.benhsucacdotbenhtruoc (
    ma_tien_su                BIGINT GENERATED ALWAYS AS IDENTITY,
    ma_ho_so                  BIGINT NOT NULL,

    tung_co_dot_tuong_tu      BOOLEAN,
    tuoi_khoi_phat            SMALLINT,
    so_dot_truoc              INTEGER,
    kieu_dien_bien            VARCHAR,
    bieu_hien_san_phu         BOOLEAN,
    bieu_hien_phu_mach        BOOLEAN,
    bieu_hien_khac_ghi_ro     TEXT,

    da_tung_nhap_vien         VARCHAR(10),
    so_lan_nhap_vien          INTEGER,
    thoi_gian_tu_dot_gan_nhat NUMERIC,
    dien_bien_cac_dot_truoc   TEXT,

    CONSTRAINT pk_benhsucacdotbenhtruoc PRIMARY KEY (ma_tien_su),
    CONSTRAINT uq_benhsucacdotbenhtruoc_hoso UNIQUE (ma_ho_so),
    CONSTRAINT fk_benhsucacdotbenhtruoc_benh_an_man FOREIGN KEY (ma_ho_so)
        REFERENCES public.benhanmaydayman (ma_ho_so) ON DELETE RESTRICT,
    CONSTRAINT ck_benh_su_tuoi CHECK (tuoi_khoi_phat >= 0),
    CONSTRAINT ck_benh_su_so_dot CHECK (so_dot_truoc >= 0),
    CONSTRAINT ck_benh_su_so_lan_nhap_vien CHECK (so_lan_nhap_vien >= 0),
    CONSTRAINT ck_benh_su_da_tung_nhap_vien CHECK (
        da_tung_nhap_vien IN ('Có', 'Không', 'Không rõ')
    ),
    CONSTRAINT ck_benh_su_nhap_vien_so_lan_nhat_quan CHECK (
        (da_tung_nhap_vien = 'Có' AND (so_lan_nhap_vien IS NULL OR so_lan_nhap_vien > 0))
        OR (da_tung_nhap_vien = 'Không' AND so_lan_nhap_vien = 0)
        OR (da_tung_nhap_vien = 'Không rõ' AND so_lan_nhap_vien IS NULL)
        OR (da_tung_nhap_vien IS NULL AND so_lan_nhap_vien IS NULL)
    ),
    CONSTRAINT ck_benh_su_thoi_gian CHECK (
        thoi_gian_tu_dot_gan_nhat >= 0
        AND thoi_gian_tu_dot_gan_nhat < 'Infinity'::NUMERIC
    )
);

