CREATE TABLE public.loainghiemphap (
    ma_nghiem_phap       BIGINT GENERATED ALWAYS AS IDENTITY,
    ten_nghiem_phap      VARCHAR(150) NOT NULL,
    phuong_phap_thuc_hien TEXT,
    thoi_gian_chuan      NUMERIC(10,2),
    thoi_diem_tao        TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    thoi_diem_cap_nhat   TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_loai_nghiem_phap PRIMARY KEY (ma_nghiem_phap),
