);

CREATE TABLE public.ketquacanlamsang (
    ma_ket_qua_can_lam_sang    BIGINT GENERATED ALWAYS AS IDENTITY,
    ma_phien_kham              BIGINT NOT NULL,
    loai_ket_qua_can_lam_sang  VARCHAR(3) NOT NULL,
    wbc                        NUMERIC(12,4),
    crp                        NUMERIC(12,4),
    ige_toan_phan              NUMERIC(12,4),
    can_lam_sang_khac_ghi_chu  TEXT,
    xet_nghiem_khac            TEXT,
    thoi_diem_thuc_hien        TIMESTAMPTZ,
    thoi_diem_cap_nhat         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_kqcls PRIMARY KEY (ma_ket_qua_can_lam_sang),
    CONSTRAINT uq_kqcls_ma_loai UNIQUE (ma_ket_qua_can_lam_sang, loai_ket_qua_can_lam_sang),
    CONSTRAINT fk_kqcls_phien_kham FOREIGN KEY (ma_phien_kham, loai_ket_qua_can_lam_sang)
        REFERENCES public.phienkham (ma_phien_kham, loai_benh_an) ON DELETE RESTRICT,
    CONSTRAINT ck_kqcls_loai CHECK (loai_ket_qua_can_lam_sang IN ('CAP', 'MAN')),
    CONSTRAINT ck_kqcls_wbc CHECK (wbc >= 0 AND wbc < 'Infinity'::NUMERIC),
    CONSTRAINT ck_kqcls_crp CHECK (crp >= 0 AND crp < 'Infinity'::NUMERIC),
    CONSTRAINT ck_kqcls_ige CHECK (ige_toan_phan >= 0 AND ige_toan_phan < 'Infinity'::NUMERIC)
);

CREATE TABLE public.ketquacanlamsangcap (
    ma_ket_qua_can_lam_sang BIGINT,
    loai_ket_qua_can_lam_sang VARCHAR(3) GENERATED ALWAYS AS ('CAP'::VARCHAR(3)) STORED,
    lym          NUMERIC(12,4),
    neu          NUMERIC(12,4),
    plt          NUMERIC(12,4),
    tryptase_cap NUMERIC(12,4),
    tryptase_nen NUMERIC(12,4),
    nlr          NUMERIC GENERATED ALWAYS AS (round(neu / nullif(lym, 0), 6)) STORED,
    plr          NUMERIC GENERATED ALWAYS AS (round(plt / nullif(lym, 0), 6)) STORED,

    CONSTRAINT pk_kqcls_cap PRIMARY KEY (ma_ket_qua_can_lam_sang),
    CONSTRAINT fk_kqcls_cap_cha FOREIGN KEY (ma_ket_qua_can_lam_sang, loai_ket_qua_can_lam_sang)
        REFERENCES public.ketquacanlamsang (ma_ket_qua_can_lam_sang, loai_ket_qua_can_lam_sang)
        ON DELETE CASCADE,
    CONSTRAINT ck_kqcls_cap_lym CHECK (lym >= 0 AND lym < 'Infinity'::NUMERIC),
    CONSTRAINT ck_kqcls_cap_neu CHECK (neu >= 0 AND neu < 'Infinity'::NUMERIC),
    CONSTRAINT ck_kqcls_cap_plt CHECK (plt >= 0 AND plt < 'Infinity'::NUMERIC),
    CONSTRAINT ck_kqcls_cap_tryptase_cap CHECK (tryptase_cap >= 0 AND tryptase_cap < 'Infinity'::NUMERIC),
    CONSTRAINT ck_kqcls_cap_tryptase_nen CHECK (tryptase_nen >= 0 AND tryptase_nen < 'Infinity'::NUMERIC)
);

CREATE TABLE public.ketquacanlamsangman (
    ma_ket_qua_can_lam_sang BIGINT,
    loai_ket_qua_can_lam_sang VARCHAR(3) GENERATED ALWAYS AS ('MAN'::VARCHAR(3)) STORED,
    test_huyet_thanh_tu_than  VARCHAR(12),
    ige_khang_tpo_ket_qua     VARCHAR(12),
    bat_ket_qua               VARCHAR(12),
    ige_khang_il24_ket_qua    VARCHAR(12),
    asst_duong_kinh_mm        NUMERIC(12,4),
    eo                        NUMERIC(12,4),
    ba_bach_cau               NUMERIC(12,4),
    anti_tpo                  NUMERIC(12,4),
    tsh                       NUMERIC(12,4),
    ft4                       NUMERIC(12,4),
    ft3                       NUMERIC(12,4),
    mau_lang_2h               NUMERIC(12,4),
    mau_lang_1h               NUMERIC(12,4),
    ana_hep2                  VARCHAR(12),
    sieu_am_tuyen_giap        TEXT,

    CONSTRAINT pk_kqcls_man PRIMARY KEY (ma_ket_qua_can_lam_sang),
    CONSTRAINT fk_kqcls_man_cha FOREIGN KEY (ma_ket_qua_can_lam_sang, loai_ket_qua_can_lam_sang)
        REFERENCES public.ketquacanlamsang (ma_ket_qua_can_lam_sang, loai_ket_qua_can_lam_sang)
        ON DELETE CASCADE,
    CONSTRAINT ck_kqcls_man_test_ht CHECK (test_huyet_thanh_tu_than IN ('Duong tinh', 'Am tinh', 'Chua lam')),
    CONSTRAINT ck_kqcls_man_ige_tpo CHECK (ige_khang_tpo_ket_qua IN ('Duong tinh', 'Am tinh', 'Chua lam')),
    CONSTRAINT ck_kqcls_man_bat CHECK (bat_ket_qua IN ('Duong tinh', 'Am tinh', 'Chua lam')),
    CONSTRAINT ck_kqcls_man_ige_il24 CHECK (ige_khang_il24_ket_qua IN ('Duong tinh', 'Am tinh', 'Chua lam')),
    CONSTRAINT ck_kqcls_man_asst CHECK (asst_duong_kinh_mm >= 0 AND asst_duong_kinh_mm < 'Infinity'::NUMERIC),
    CONSTRAINT ck_kqcls_man_eo CHECK (eo >= 0 AND eo < 'Infinity'::NUMERIC),
    CONSTRAINT ck_kqcls_man_ba CHECK (ba_bach_cau >= 0 AND ba_bach_cau < 'Infinity'::NUMERIC),
    CONSTRAINT ck_kqcls_man_anti_tpo CHECK (anti_tpo >= 0 AND anti_tpo < 'Infinity'::NUMERIC),
    CONSTRAINT ck_kqcls_man_tsh CHECK (tsh >= 0 AND tsh < 'Infinity'::NUMERIC),
    CONSTRAINT ck_kqcls_man_ft4 CHECK (ft4 >= 0 AND ft4 < 'Infinity'::NUMERIC),
    CONSTRAINT ck_kqcls_man_ft3 CHECK (ft3 >= 0 AND ft3 < 'Infinity'::NUMERIC),
    CONSTRAINT ck_kqcls_man_ml_2h CHECK (mau_lang_2h >= 0 AND mau_lang_2h < 'Infinity'::NUMERIC),
    CONSTRAINT ck_kqcls_man_ml_1h CHECK (mau_lang_1h >= 0 AND mau_lang_1h < 'Infinity'::NUMERIC),
    CONSTRAINT ck_kqcls_man_ana CHECK (ana_hep2 IN ('Duong tinh', 'Am tinh')),
    CONSTRAINT ck_kqcls_man_asst_logic CHECK (
        asst_duong_kinh_mm IS NULL OR test_huyet_thanh_tu_than IS NOT DISTINCT FROM 'Duong tinh'
    )
);

CREATE TABLE public.phiennghiemphapkichthich (
    ma_phien_nghiem_phap       BIGINT GENERATED ALWAYS AS IDENTITY,
    ma_phien_kham              BIGINT NOT NULL,
    ngung_khang_histamine      BOOLEAN,
    thoi_gian_ngung_histamine  NUMERIC(8,2),
    ngung_corticoid            BOOLEAN,
    thoi_gian_ngung_corticoid  NUMERIC(8,2),
    thoi_diem_cap_nhat         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_phien_nghiem_phap PRIMARY KEY (ma_phien_nghiem_phap),
    CONSTRAINT uq_phien_nghiem_phap_phien_kham UNIQUE (ma_phien_kham),
    CONSTRAINT fk_phien_np_phien_kham_man FOREIGN KEY (ma_phien_kham)
        REFERENCES public.phienkhamman (ma_phien_kham) ON DELETE RESTRICT,
    CONSTRAINT ck_phien_np_histamine_val CHECK (
        thoi_gian_ngung_histamine >= 0 AND thoi_gian_ngung_histamine < 'Infinity'::NUMERIC
    ),
    CONSTRAINT ck_phien_np_corticoid_val CHECK (
        thoi_gian_ngung_corticoid >= 0 AND thoi_gian_ngung_corticoid < 'Infinity'::NUMERIC
    ),
    CONSTRAINT ck_phien_np_histamine CHECK (
        thoi_gian_ngung_histamine IS NULL OR ngung_khang_histamine IS TRUE
    ),
    CONSTRAINT ck_phien_np_corticoid CHECK (
        thoi_gian_ngung_corticoid IS NULL OR ngung_corticoid IS TRUE
    )
);

CREATE TABLE public.chitietketquanghiemphap (
    ma_chi_tiet_ket_qua_nghiem_phap BIGINT GENERATED ALWAYS AS IDENTITY,
    ma_phien_nghiem_phap            BIGINT NOT NULL,
    loai_nghiem_phap                BIGINT NOT NULL,
    ket_qua                        VARCHAR(12),
    nguong_gia_tri_so               NUMERIC(12,4),
    nguong_gia_tri_chu              TEXT,
    don_vi_do                       VARCHAR(30),
    diem_ngua_nrs                   SMALLINT,
    diem_bong_rat_nrs               SMALLINT,
    diem_dau_nrs                    SMALLINT,
    can_nguyen_khac_ten             TEXT,

    CONSTRAINT pk_chi_tiet_kqnp PRIMARY KEY (ma_chi_tiet_ket_qua_nghiem_phap),
    CONSTRAINT fk_chi_tiet_kqnp_phien FOREIGN KEY (ma_phien_nghiem_phap)
        REFERENCES public.phiennghiemphapkichthich (ma_phien_nghiem_phap) ON DELETE RESTRICT,
    CONSTRAINT fk_chi_tiet_kqnp_loai FOREIGN KEY (loai_nghiem_phap)
        REFERENCES public.loainghiemphap (ma_nghiem_phap) ON DELETE RESTRICT,
    CONSTRAINT ck_chi_tiet_kqnp_ket_qua CHECK (ket_qua IN ('Duong tinh', 'Am tinh')),
    CONSTRAINT ck_chi_tiet_kqnp_nguong CHECK (
        nguong_gia_tri_so IS NULL OR nguong_gia_tri_chu IS NULL
    ),
    CONSTRAINT ck_chi_tiet_kqnp_don_vi CHECK (
        (nguong_gia_tri_so IS NULL AND nguong_gia_tri_chu IS NULL)
        OR don_vi_do IS NOT NULL
    ),
    CONSTRAINT ck_chi_tiet_kqnp_nguong_khong_am CHECK (
        don_vi_do NOT IN ('phut', 'kg', 'nm', 'diem') OR nguong_gia_tri_so >= 0
    ),
    CONSTRAINT ck_chi_tiet_kqnp_nguong_chu CHECK (btrim(nguong_gia_tri_chu) <> ''),
    CONSTRAINT ck_chi_tiet_kqnp_don_vi_val CHECK (btrim(don_vi_do) <> ''),
    CONSTRAINT ck_chi_tiet_kqnp_can_nguyen CHECK (btrim(can_nguyen_khac_ten) <> ''),
    CONSTRAINT ck_chi_tiet_kqnp_ngua_nrs CHECK (diem_ngua_nrs BETWEEN 0 AND 10),
    CONSTRAINT ck_chi_tiet_kqnp_bong_nrs CHECK (diem_bong_rat_nrs BETWEEN 0 AND 10),
    CONSTRAINT ck_chi_tiet_kqnp_dau_nrs CHECK (diem_dau_nrs BETWEEN 0 AND 10),
    CONSTRAINT ck_chi_tiet_kqnp_nguong_so CHECK (nguong_gia_tri_so < 'Infinity'::NUMERIC)
);


