CREATE TABLE public.thuoc (
    ma_thuoc           VARCHAR(50) NOT NULL,
    ten_thuoc          VARCHAR(255) NOT NULL,
    hoat_chat          VARCHAR(255),
    nhom_dieu_tri      VARCHAR(100),
    thoi_diem_tao      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    thoi_diem_cap_nhat TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_thuoc PRIMARY KEY (ma_thuoc),
    CONSTRAINT ck_thuoc_ten CHECK (btrim(ten_thuoc) <> ''),
    CONSTRAINT ck_thuoc_nhom_dieu_tri CHECK (nhom_dieu_tri IS NULL OR nhom_dieu_tri IN (
        'Khang histamine H1 TH2', 'Sinh hoc/dich', 'Uc che mien dich',
        'Corticosteroid toan than', 'Khac'
    ))
);

