    ) STORED,
    trang_thai_dung_thuoc      VARCHAR(50),
    trang_thai_ngay            VARCHAR(50) DEFAULT 'HOP_LE',
    thoi_diem_cap_nhat         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_nhatkyuashangngay PRIMARY KEY (ma_nhat_ky_uas),
