    CONSTRAINT fk_nhatkyuas_chuky FOREIGN KEY (ma_chu_ky)
        REFERENCES public.chukytheodoiuas7 (ma_chu_ky) ON DELETE RESTRICT,
    CONSTRAINT fk_nhatkyuas_benhanman FOREIGN KEY (ma_ho_so_man)
        REFERENCES public.benhanmaydayman (ma_ho_so) ON DELETE RESTRICT,
    CONSTRAINT fk_nhatkyuas_benhnhan FOREIGN KEY (ma_benh_nhan)
        REFERENCES public.benhnhan (ma_benh_nhan) ON DELETE RESTRICT,
    CONSTRAINT ck_nhatkyuas_hss CHECK (diem_san_phu_hss BETWEEN 0 AND 3),
    CONSTRAINT ck_nhatkyuas_iss CHECK (diem_ngua_iss BETWEEN 0 AND 3),
    CONSTRAINT ck_nhatkyuas_thu_may CHECK (ngay_thu_may_trong_chu_ky BETWEEN 1 AND 7)
);

