CREATE TABLE public.nhatkyaashangngay (
    ma_nhat_ky_aas       BIGINT GENERATED ALWAYS AS IDENTITY,
    ma_benh_nhan         BIGINT NOT NULL,
    ma_ho_so_man         BIGINT,
    ngay_theo_doi        DATE NOT NULL,
    co_dot_sung_phu      BOOLEAN NOT NULL DEFAULT FALSE,
    thoi_diem_xuat_hien  VARCHAR(50),
    muc_kho_chiu         SMALLINT,
    han_che_hoat_dong    SMALLINT,
    anh_huong_ngoai_hinh SMALLINT,
    do_nang_tong_the     SMALLINT,
    diem_aas_ngay        SMALLINT GENERATED ALWAYS AS (
        CASE
            WHEN co_dot_sung_phu = TRUE
            THEN muc_kho_chiu + han_che_hoat_dong +
                 anh_huong_ngoai_hinh + do_nang_tong_the
            ELSE 0
        END
    ) STORED,
    thoi_diem_cap_nhat   TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_nhatkyaashangngay PRIMARY KEY (ma_nhat_ky_aas),
    CONSTRAINT uq_nhatkyaas_benhnhan_ngay UNIQUE (ma_benh_nhan, ngay_theo_doi),
    CONSTRAINT fk_nhatkyaas_benhnhan FOREIGN KEY (ma_benh_nhan)
        REFERENCES public.benhnhan (ma_benh_nhan) ON DELETE RESTRICT,
    CONSTRAINT fk_nhatkyaas_benhanman FOREIGN KEY (ma_ho_so_man)
        REFERENCES public.benhanmaydayman (ma_ho_so) ON DELETE RESTRICT,
    CONSTRAINT ck_aas_kho_chiu CHECK (muc_kho_chiu BETWEEN 0 AND 3),
    CONSTRAINT ck_aas_han_che CHECK (han_che_hoat_dong BETWEEN 0 AND 3),
    CONSTRAINT ck_aas_ngoai_hinh CHECK (anh_huong_ngoai_hinh BETWEEN 0 AND 3),
    CONSTRAINT ck_aas_do_nang CHECK (do_nang_tong_the BETWEEN 0 AND 3)
);

