CREATE TABLE public.anhchuptonthuong (
    ma_anh                BIGINT GENERATED ALWAYS AS IDENTITY,
    ma_tep_dinh_kem       BIGINT NOT NULL,
    ma_dot_ton_thuong_da  BIGINT,
    ma_vi_tri_ton_thuong  BIGINT,
    thoi_diem_chup        TIMESTAMPTZ NOT NULL,
    moc_tien_trien        VARCHAR(50),
    diem_ngua_nrs         SMALLINT,
    diem_dau_nrs          SMALLINT,
    diem_bong_rat_nrs     SMALLINT,
    so_luong_not_san      INTEGER,
    chi_so_auas_cuc_bo    NUMERIC(5,2),
    url_anh               VARCHAR(500),
    thoi_diem_tao         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    thoi_diem_cap_nhat    TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_anhchuptonthuong PRIMARY KEY (ma_anh),
    CONSTRAINT fk_anhtonthuong_tepdinhkem FOREIGN KEY (ma_tep_dinh_kem)
        REFERENCES public.tepdinhkem (ma_tep_dinh_kem) ON DELETE RESTRICT,
    CONSTRAINT fk_anhtonthuong_dottonthuongda FOREIGN KEY (ma_dot_ton_thuong_da)
        REFERENCES public.dottonthuongda (ma_dot_ton_thuong_da) ON DELETE RESTRICT,
    CONSTRAINT fk_anhtonthuong_vitritonthuong FOREIGN KEY (ma_vi_tri_ton_thuong)
        REFERENCES public.vitritonthuong (ma_vi_tri_ton_thuong) ON DELETE RESTRICT,
    CONSTRAINT ck_anh_ngua_nrs CHECK (diem_ngua_nrs BETWEEN 0 AND 10),
    CONSTRAINT ck_anh_dau_nrs CHECK (diem_dau_nrs BETWEEN 0 AND 10),
    CONSTRAINT ck_anh_bong_rat_nrs CHECK (diem_bong_rat_nrs BETWEEN 0 AND 10),
    CONSTRAINT ck_anh_so_luong CHECK (so_luong_not_san >= 0)
);


