    (ngay_cham_diem - (ngay_thu_may_trong_chu_ky::INTEGER - 1)) STORED;

ALTER TABLE public.nhatkyuashangngay
    ADD CONSTRAINT ck_uas_chuky_ngay CHECK ((ma_chu_ky IS NULL) = (ngay_thu_may_trong_chu_ky IS NULL));

ALTER TABLE public.nhatkyuashangngay
    ADD CONSTRAINT fk_uas_chuky_benhnhan_ngay FOREIGN KEY (ma_chu_ky, ma_benh_nhan, ngay_bat_dau_chu_ky) REFERENCES public.chukytheodoiuas7 (ma_chu_ky, ma_benh_nhan, ngay_bat_dau) ON DELETE RESTRICT;

ALTER TABLE public.nhatkyuashangngay
    ALTER COLUMN trang_thai_ngay SET NOT NULL;

ALTER TABLE public.nhatkyuashangngay
    ADD CONSTRAINT ck_uas_trangthai CHECK (trang_thai_ngay IN ('HOP_LE', 'KHONG_HOP_LE'));

CREATE VIEW public.v_chukytheodoiuas7 AS
SELECT c.*, (
    SELECT count(*)::SMALLINT FROM public.nhatkyuashangngay n
    WHERE n.ma_chu_ky = c.ma_chu_ky AND n.trang_thai_ngay = 'HOP_LE'
) AS so_ngay_hop_le
FROM public.chukytheodoiuas7 c;

