CREATE TRIGGER trg_benhanmaydaycap_cap_nhat BEFORE UPDATE ON public.benhanmaydaycap FOR EACH ROW EXECUTE FUNCTION public.fn_cap_nhat_thoi_gian();

CREATE TRIGGER trg_nhatkyuashangngay_cap_nhat BEFORE UPDATE ON public.nhatkyuashangngay FOR EACH ROW EXECUTE FUNCTION public.fn_cap_nhat_thoi_gian();

CREATE TRIGGER trg_sanglocbaodongdo_cap_nhat
    BEFORE UPDATE ON public.sanglocbaodongdo FOR EACH ROW
    EXECUTE FUNCTION public.fn_cap_nhat_thoi_gian();

CREATE INDEX idx_sanglocbaodongdo_benhnhan
    ON public.sanglocbaodongdo (ma_benh_nhan)
    WHERE ma_benh_nhan IS NOT NULL;

CREATE INDEX idx_sanglocbaodongdo_nguyco_thoigian
    ON public.sanglocbaodongdo (thoi_diem_hoan_tat DESC)
    WHERE co_nguy_co_phan_ve;

COMMENT ON TABLE public.sanglocbaodongdo IS
    'Mỗi dòng là một lượt sàng lọc báo động đỏ đã hoàn tất trước đăng nhập hoặc trước bước định danh.';

COMMENT ON COLUMN public.sanglocbaodongdo.ma_phien_ung_dung IS
    'Mã UUID duy nhất để ứng dụng gửi lại an toàn khi retry cùng một lượt sàng lọc.';

COMMENT ON COLUMN public.sanglocbaodongdo.da_nhan_nut_goi_cap_cuu IS
    'Chỉ ghi nhận thao tác yêu cầu mở cuộc gọi; không khẳng định cuộc gọi đã kết nối.';

COMMENT ON COLUMN public.sanglocbaodongdo.co_kho_tho_kho_khe_nghen_hong IS
    'Khó thở, thở khò khè hoặc cảm giác nghẹn họng.';

COMMENT ON COLUMN public.sanglocbaodongdo.co_chong_mat_tuc_nguc_sap_ngat IS
    'Chóng mặt, xây xẩm mặt mày, tức ngực hoặc cảm thấy sắp ngất.';

COMMENT ON COLUMN public.sanglocbaodongdo.co_sung_moi_luoi_co_hong IS
    'Sưng nề nhanh ở môi, lưỡi hoặc cổ họng.';

COMMENT ON COLUMN public.sanglocbaodongdo.co_dau_bung_non_lien_tuc IS
    'Đau bụng quặn hoặc nôn mửa liên tục.';

CREATE TRIGGER trg_nhatkyaashangngay_cap_nhat BEFORE UPDATE ON public.nhatkyaashangngay FOR EACH ROW EXECUTE FUNCTION public.fn_cap_nhat_thoi_gian();

CREATE TRIGGER trg_ketquaproms_cap_nhat BEFORE UPDATE ON public.ketquaproms FOR EACH ROW EXECUTE FUNCTION public.fn_cap_nhat_thoi_gian();

