CREATE INDEX idx_donthuoc_ma_phien_kham ON public.donthuoc (ma_phien_kham);

CREATE INDEX idx_chitiettonthuongsanphu_ma_dac_diem_san_phu ON public.chitiettonthuongsanphu (ma_dac_diem_san_phu);

CREATE INDEX idx_hosobenhan_subtype_cap ON public.hosobenhan (ma_subtype_cap) WHERE ma_subtype_cap IS NOT NULL;

CREATE INDEX idx_hosobenhan_subtype_man ON public.hosobenhan (ma_subtype_man) WHERE ma_subtype_man IS NOT NULL;

CREATE INDEX idx_phienkham_subtype_cap ON public.phienkham (ma_subtype_cap) WHERE ma_subtype_cap IS NOT NULL;

CREATE INDEX idx_phienkham_subtype_man ON public.phienkham (ma_subtype_man) WHERE ma_subtype_man IS NOT NULL;

CREATE INDEX idx_ketquacanlamsang_subtype_cap ON public.ketquacanlamsang (ma_subtype_cap) WHERE ma_subtype_cap IS NOT NULL;

CREATE INDEX idx_ketquacanlamsang_subtype_man ON public.ketquacanlamsang (ma_subtype_man) WHERE ma_subtype_man IS NOT NULL;

COMMENT ON COLUMN public.chitietdonthuoc.ma_ke_hoach_dieu_tri IS 'Mã tham chiếu kế hoạch từ hệ thống ngoài, không phải FK nội bộ; NULL nếu không sử dụng.';

COMMENT ON COLUMN public.danhgiamucdohoatdongbenh.ma_nguoi_danh_gia IS 'Người thực hiện đánh giá, tham chiếu nguoi; có thể là nhân viên hoặc bệnh nhân.';

COMMENT ON VIEW public.v_chukytheodoiuas7 IS 'Đọc chu kỳ kèm số ngày HOP_LE tính trực tiếp từ nhật ký. Không ghi so_ngay_hop_le vào bảng chu kỳ.';

COMMENT ON COLUMN public.chitietketquanghiemphap.la_can_nguyen_khac IS 'Phải khớp danh mục loại nghiệm pháp; TRUE bắt buộc can_nguyen_khac_ten.';

COMMIT;
